int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    int a[105], b[105];
    for (int i = 0; i < n; i++) {
        scanf("%d %d", &a[i], &b[i]);
    }

    /* dp[day][mask]:
       after considering days 1..day, with set of movies watched at least once = mask,
       maximum happiness.
       Since there are only 31 days, any movie shown at least once can be watched at most
       twice beneficially (100 first time, 50 later), but state only needs whether first
       watch already happened. Each day choose one available movie.

       This standard bitmask DP works because n is intended small.
    */
    int maxMask = 1 << n;
    static int dp[32][1 << 15];
    for (int d = 0; d <= 31; d++) {
        for (int m = 0; m < maxMask; m++) dp[d][m] = -1;
    }
    dp[0][0] = 0;

    for (int day = 1; day <= 31; day++) {
        for (int mask = 0; mask < maxMask; mask++) {
            if (dp[day - 1][mask] < 0) continue;
            for (int i = 0; i < n; i++) {
                if (a[i] <= day && day <= b[i]) {
                    int nmask = mask | (1 << i);
                    int add = (mask & (1 << i)) ? 50 : 100;
                    if (dp[day][nmask] < dp[day - 1][mask] + add) {
                        dp[day][nmask] = dp[day - 1][mask] + add;
                    }
                }
            }
        }
    }

    int ans = 0;
    for (int mask = 0; mask < maxMask; mask++) {
        if (dp[31][mask] > ans) ans = dp[31][mask];
    }

    printf("%d\n", ans);
    return 0;
}

