using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<pair<int, int>> movies(n);
    for (int i = 0; i < n; i++) {
        cin >> movies[i].first >> movies[i].second;
    }

    const int DAYS = 31;
    int max_happiness = 0;

    // Try all subsets of movies
    for (int mask = 0; mask < (1 << n); mask++) {
        vector<int> watch_count(DAYS + 1, 0);
        bool valid = true;

        for (int i = 0; i < n; i++) {
            if (mask & (1 << i)) {
                int a = movies[i].first;
                int b = movies[i].second;
                for (int d = a; d <= b; d++) {
                    if (d > DAYS) break;
                    watch_count[d]++;
                    if (watch_count[d] > 1) {
                        valid = false;
                        break;
                    }
                }
                if (!valid) break;
            }
        }
        if (!valid) continue;

        // Now we have a set of movies with no overlapping days
        // We can watch each movie at most once per day, but here each movie occupies its entire interval
        // Actually the problem says: watch one movie each day from the available screenings.
        // If we select a movie, we must watch it on some day in its interval.
        // Since we can only watch one movie per day, we need to assign days to selected movies.
        // This subset approach only works if each selected movie gets exactly one day.
        // For maximum happiness, if we select a movie, we watch it once -> 100.
        // We can watch the same movie again on another day -> 50 more.
        // So we need to consider multiple viewings.

        // Let's instead do DP over days.
    }

    // DP over days
    // dp[day][mask] = max happiness up to day, mask indicates which movies have been watched at least once
    // But n can be up to? Not given, but 31 days, we can have at most 31 movies (one per day)
    // So n <= 31, mask up to 2^31 too large.
    // Better: since only 31 days, we can consider all possible sequences of movies watched each day.
    // Use DP over days with state = set of movies already seen (bitmask up to 2^n).
    // If n is small (<=20) it's fine, else we need another approach.

    // Let's assume n <= 20 for bitmask DP.
    // If n > 20, we can compress because only 31 days, we can't watch more than 31 distinct movies.
    // So we can limit to at most 31 movies.

    // We'll do DP over days with bitmask of seen movies.
    // But we need to know which movies are available each day.
    vector<vector<int>> available(DAYS + 1);
    for (int i = 0; i < n; i++) {
        for (int d = movies[i].first; d <= movies[i].second; d++) {
            if (d <= DAYS) available[d].push_back(i);
        }
    }

    // If n is large, we map only movies that appear in schedule.
    // But for simplicity, assume n <= 20 for this solution.
    // Actually let's do DP with map for state compression.

    // Since days are only 31, we can do DP with map from bitmask to max happiness.
    unordered_map<int, int> dp;
    dp[0] = 0;

    for (int d = 1; d <= DAYS; d++) {
        unordered_map<int, int> ndp;
        for (auto &[mask, val] : dp) {
            // Option: watch nothing today
            ndp[mask] = max(ndp[mask], val);
            // Option: watch some movie available today
            for (int movie : available[d]) {
                int bit = 1 << movie;
                int new_mask = mask | bit;
                int happiness = val;
                if (mask & bit) {
                    happiness += 50; // already seen
                } else {
                    happiness += 100; // first time
                }
                ndp[new_mask] = max(ndp[new_mask], happiness);
            }
        }
        dp = move(ndp);
    }

    int answer = 0;
    for (auto &[mask, val] : dp) {
        answer = max(answer, val);
    }
    cout << answer << "\n";

    return 0;
}

