import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine());
        int[] start = new int[n];
        int[] end = new int[n];
        for (int i = 0; i < n; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            start[i] = Integer.parseInt(st.nextToken());
            end[i] = Integer.parseInt(st.nextToken());
        }

        // dp[mask][last] = max happiness ending with movie last (or 0 for none)
        // but n <= 10, 31 days, we can brute force all subsets order
        int maxHappiness = 0;
        int fullMask = (1 << n) - 1;

        // dp[mask][last] where last is movie index (0..n-1) or -1 for no last
        int[][] dp = new int[1 << n][n];
        for (int[] row : dp) Arrays.fill(row, -1);

        // Initialize with watching one movie
        for (int i = 0; i < n; i++) {
            int mask = 1 << i;
            dp[mask][i] = 100; // first time
        }

        for (int mask = 0; mask < (1 << n); mask++) {
            for (int last = 0; last < n; last++) {
                if (dp[mask][last] == -1) continue;
                // try to add another movie next
                for (int next = 0; next < n; next++) {
                    if ((mask & (1 << next)) != 0) continue;
                    // check if schedule feasible: end[last] < start[next] or end[next] < start[last]?
                    // We need to place movies on distinct days, order matters.
                    // Since we are building sequence, we assume last is watched last.
                    // next movie must start after last ends (or we can reorder?)
                    // Actually we are constructing a sequence, so we enforce order.
                    if (end[last] < start[next]) {
                        int newMask = mask | (1 << next);
                        int add = 100; // first time for next
                        // But if next was already seen? In this construction, we only add unseen movies.
                        // So always first time.
                        dp[newMask][next] = Math.max(dp[newMask][next], dp[mask][last] + add);
                    }
                }
            }
        }

        // Now we have sequences, but we can also watch movies multiple times.
        // Actually we need to consider rewatching. Our DP only considers each movie once.
        // We need to allow rewatching.
        // Let's think differently: n <= 10, days 31. We can brute force assignment of movies to days.
        // Each day we choose a movie (or none). That's 31^10 too big.
        // Better: Since n small, we can consider all possible permutations of movies (with repeats allowed up to 2 times per movie).
        // But each movie can be watched at most twice (first time 100, second 50, further no gain).
        // So each movie can appear 0,1,2 times in optimal schedule.
        // So we can try all subsets with multiplicities, then order them.
        // Let's do DP over days instead.

        // Alternative: Since days are only 31, we can do DP over days with state being which movies have been seen once.
        // dp[day][mask] = max happiness up to day, where mask indicates movies seen at least once.
        // But we also need to know if a movie has been seen twice? Actually second viewing gives 50, third gives 0.
        // So we need to know count per movie: 0,1,2+. That's 3^10 = 59049, feasible.
        // Let's encode state as base-3 number: 0=not seen, 1=seen once, 2=seen twice or more.

        int[] pow3 = new int[n+1];
        pow3[0] = 1;
        for (int i = 1; i <= n; i++) pow3[i] = pow3[i-1] * 3;
        int states = pow3[n];

        int[] dpDay = new int[states];
        Arrays.fill(dpDay, -1);
        dpDay[0] = 0;

        // Precompute for each movie which days it is available
        boolean[][] available = new boolean[n][32]; // 1-indexed days
        for (int i = 0; i < n; i++) {
            for (int d = start[i]; d <= end[i]; d++) {
                available[i][d] = true;
            }
        }

        for (int day = 1; day <= 31; day++) {
            int[] nextDp = new int[states];
            Arrays.fill(nextDp, -1);
            for (int state = 0; state < states; state++) {
                if (dpDay[state] == -1) continue;
                // Option: skip watching any movie today
                nextDp[state] = Math.max(nextDp[state], dpDay[state]);
                // Option: watch a movie i
                for (int i = 0; i < n; i++) {
                    if (!available[i][day]) continue;
                    int count = (state / pow3[i]) % 3;
                    if (count >= 2) continue; // no gain, but we could still watch? No gain, so skip.
                    int gain = (count == 0) ? 100 : 50;
                    int newState = state + pow3[i]; // increment count
                    nextDp[newState] = Math.max(nextDp[newState], dpDay[state] + gain);
                }
            }
            dpDay = nextDp;
        }

        int answer = 0;
        for (int state = 0; state < states; state++) {
            answer = Math.max(answer, dpDay[state]);
        }
        System.out.println(answer);
    }
}

