            movies[i][1] = sc.nextInt(); // b_i
        }

        // Sort by end day
        Arrays.sort(movies, (x, y) -> x[1] - y[1]);

        boolean[] used = new boolean[32]; // days 1..31
        int distinct = 0;

        for (int[] movie : movies) {
            int a = movie[0], b = movie[1];
            // Find largest available day in [a, b]
            for (int d = b; d >= a; d--) {
                if (!used[d]) {
                    used[d] = true;
                    distinct++;
                    break;
                }
            }
        }

        // Days with no movie available? Assume all 31 days have at least one movie
        // Total happiness = distinct * 100 + (31 - distinct) * 50
        int happiness = distinct * 100 + (31 - distinct) * 50;
        System.out.println(happiness);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int n = fs.nextInt();

        boolean[][] shown = new boolean[32][n]; // days 1..31
        for (int i = 0; i < n; i++) {
            int a = fs.nextInt();
            int b = fs.nextInt();
            for (int d = a; d <= b; d++) {
                shown[d][i] = true;
            }
        }

        // dp[mask]: maximum happiness after processing current day,
        // where mask represents which movies have been watched at least once.
        int maxMask = 1 << n;
        int[] dp = new int[maxMask];
        Arrays.fill(dp, -1);
        dp[0] = 0;

        for (int day = 1; day <= 31; day++) {
            int[] next = new int[maxMask];
            Arrays.fill(next, -1);

            for (int mask = 0; mask < maxMask; mask++) {
                if (dp[mask] < 0) continue;

                for (int movie = 0; movie < n; movie++) {
                    if (!shown[day][movie]) continue;

                    int nmask = mask | (1 << movie);
                    int gain = ((mask & (1 << movie)) == 0) ? 100 : 50;
                    next[nmask] = Math.max(next[nmask], dp[mask] + gain);
                }
            }

            dp = next;
        }

        int ans = 0;
        for (int v : dp) ans = Math.max(ans, v);
        System.out.println(ans);
    }
}

import sys

def main():
    input = sys.stdin.readline
    n = int(input())
    intervals = []
    for _ in range(n):
        a, b = map(int, input().split())
        intervals.append((a, b))

    # dp[mask]: maximum happiness after processing current day,
    # where mask represents movies watched at least once so far.
    # n is small enough for bitmask DP in this problem.
    INF = -10**18
    size = 1 << n
    dp = [INF] * size
    dp[0] = 0

    for day in range(1, 32):
        ndp = [INF] * size
        available = []
        for i, (a, b) in enumerate(intervals):
            if a <= day <= b:
                available.append(i)

        for mask in range(size):
            if dp[mask] == INF:
                continue
            # Choose one available movie to watch
            for i in available:
                if (mask >> i) & 1:
                    nmask = mask
                    gain = 50
                else:
                    nmask = mask | (1 << i)
                    gain = 100
                if ndp[nmask] < dp[mask] + gain:
                    ndp[nmask] = dp[mask] + gain
        dp = ndp

    print(max(dp))

